            if days_apart(entry.date, candidate.date) > max_days:
                continue
            found = candidate
            break
        if found is None:
            result.unmatched_entries.append(entry)
        else:
            remaining.remove(found)
            result.pairs.append((entry, found))
    result.unmatched_statements = remaining
    return result

